#!/usr/bin/env python3
from pathlib import Path
import subprocess,tempfile
root=Path(__file__).resolve().parents[1];core=root/'components/pc98core'
code='\n#include <assert.h>\n#include <stdio.h>\n#include <compiler.h>\n#include <pc98.h>\n#include "viewint.h"\n#include "compose.c"\nMachineState g_mstat; int g_pc98_draw_enabled=1; UINT g_frames_composed;\nGdc g_tgdc,g_ggdc; VideoCtl g_vid; VideoReq g_vreq;\nUINT8 g_text_dirty[0x1000]; volatile long long g_prof_draw;\nstatic unsigned timing_calls;\nvoid gdc_timing(void){timing_calls++;}\nvoid textview_init(void){} void grphview_init(void){}\nvoid textview_draw(int a,int b,int c){(void)a;(void)b;(void)c;}\nvoid grphview_draw(UINT a,int b){(void)a;(void)b;}\nint textview_has_blink(void){return 0;}\nUINT16 *host_frame(int *w,int *h,int *stride){*w=640;*h=400;*stride=1280;return NULL;}\nint main(void){\n memset(g_gpix,0x5a,sizeof g_gpix);memset(g_tpix,0x30,sizeof g_tpix);\n memset(g_line_dirty,0xa5,sizeof g_line_dirty);\n g_geom.lines=123;g_vreq.layout=g_vreq.palette=1;g_mstat.drawframe=0;\n /* A previously queued compositor can still be reading all these buffers. */\n video_frame();\n for(unsigned i=0;i<sizeof g_gpix;i++)assert(((UINT8*)g_gpix)[i]==0x5a);\n for(unsigned i=0;i<sizeof g_tpix;i++)assert(g_tpix[i]==0x30);\n assert(g_geom.lines==123 && g_vreq.layout && g_vreq.palette && timing_calls);\n g_mstat.drawframe=1;video_frame();\n assert(!g_vreq.layout && !g_vreq.palette && g_geom.lines!=123);\n for(unsigned i=0;i<sizeof g_gpix;i++)assert(((UINT8*)g_gpix)[i]==0);\n puts("PASS: skipped render preserves queued compositor pixels; timing updates and layout/palette remain pending until a render");\n}\n'
with tempfile.TemporaryDirectory() as tmp:
 p=Path(tmp);(p/'test.c').write_text(code)
 subprocess.run(['gcc','-std=gnu99','-O1','-g','-ffunction-sections','-fdata-sections','-fsanitize=address,undefined','-I'+str(core),'-I'+str(core/'include'),'-I'+str(core/'video'),str(p/'test.c'),'-Wl,--gc-sections','-o',str(p/'test')],check=True)
 subprocess.run([str(p/'test')],check=True)
